// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 fundAmount, uint256 withdrawAmount) public {
        vm.assume(fundAmount > 0 && fundAmount < type(uint120).max);
        vm.assume(withdrawAmount > 0 && withdrawAmount < type(uint120).max);
        vm.deal(address(c), fundAmount);
        vm.prank(c.owner());
        bool ok = true;
        try c.withdraw(withdrawAmount) {} catch { ok = false; }
        bool ok2 = true;
        try c.withdrawAll() {} catch { ok2 = false; }
        assertTrue(ok2 ? address(c).balance == 0 : true);
    }
}
